{
    if (!string) {
        return GF_BAD_PARAM;
    }

    const char *hex_str = string;
    if (hex_str[0] == '0' && hex_str[1] == 'x') {
        hex_str += 2;
    }

    int length = 0;
    while (hex_str[length] != '\0') {
        length++;
    }

    if (length % 2 != 0) {
        return GF_BAD_PARAM;
    }

    if (length > 32) {
        return GF_BAD_PARAM;
    }

    int i;
    for (i = 0; i < length; i += 2) {
        char byte_str[3] = { hex_str[i], hex_str[i + 1], '\0' };
        unsigned int byte_value;
        if (sscanf(byte_str, "%x", &byte_value) != 1) {
            return GF_BAD_PARAM;
        }

        value[i / 2] = (unsigned char)byte_value;
    }

    for (; i < 32; i += 2) {
        value[i / 2] = 0;
    }

    return GF_OK;
}

GF_Err parse_hex_string(const char *string, bin128 value) {
    if (!string || !value) {
        return GF_BAD_PARAM;
    }

    const char *hex = string;
    if (hex[0] == '0' && hex[1] == 'x') {
        hex += 2;
    }

    unsigned int length = 0;
    while (hex[length] != '\0') {
        length++;
    }

    if (length % 2 != 0) {
        return GF_BAD_PARAM;
    }

    unsigned int byte_count = length / 2;
    if (byte_count > 16) {
        return GF_BAD_PARAM;
    }

    for (unsigned int i = 0; i < 16; i++) {
        value[i] = 0;
    }

    for (unsigned int i = 0; i < byte_count; i++) {
        char byte_str[3] = {hex[2 * i], hex[2 * i + 1], '\0'};
        unsigned int byte_value;
        sscanf(byte_str, "%x", &byte_value);
        value[15 - i] = (unsigned char)byte_value;
    }

    return GF_OK;
}

GF_Err parse_hex_to_bin128(const char *string, bin128 value) {
    if (!string) {
        return GF_BAD_PARAM;
    }

    const char *ptr = string;
    if (ptr[0] == '0' && (ptr[1] == 'x' || ptr[1] == 'X')) {
        ptr += 2;
    }

    int len = 0;
    while (ptr[len] && len < 32) {
        len++;
    }

    if (len % 2 != 0) {
        return GF_BAD_PARAM;
    }

    for (int i = 0; i < len / 2; i++) {
        char high = ptr[i * 2];
        char low = ptr[i * 2 + 1];

        if ((high < '0' || high > '9') && (high < 'a' || high > 'f') && (high < 'A' || high > 'F')) {
            return GF_BAD_PARAM;
        }
        if ((low < '0' || low > '9') && (low < 'a' || low > 'f') && (low < 'A' || low > 'F')) {
            return GF_BAD_PARAM;
        }

        value[i] = ((high >= 'A' && high <= 'F') ? (high - 'A' + 10) : ((high >= 'a' && high <= 'f') ? (high - 'a' + 10) : (high - '0'))) << 4;
        value[i] |= ((low >= 'A' && low <= 'F') ? (low - 'A' + 10) : ((low >= 'a' && low <= 'f') ? (low - 'a' + 10) : (low - '0')));
    }

    if (len / 2 != 16) {
        return GF_BAD_PARAM;
    }

    return GF_OK;
}

GF_Err parse_hex_to_bin128(const char *string, bin128 value) {
    if (!string) {
        return GF_BAD_PARAM;
    }

    const char *hex = string;
    if (hex[0] == '0' && hex[1] == 'x') {
        hex += 2;
    }

    if (strlen(hex) % 2 != 0) {
        return GF_BAD_PARAM;
    }

    unsigned int i;
    int j;
    for (i = 0, j = 0; i < strlen(hex); i += 2, j++) {
        char byte_str[3] = {hex[i], hex[i + 1], '\0'};
        char *end;
        unsigned int byte = (unsigned int)strtoul(byte_str, &end, 16);
        if (*end != '\0') {
            return GF_BAD_PARAM;
        }
        value[j] = (uint8_t)byte;
    }

    if (j != 16) {
        return GF_BAD_PARAM;
    }

    return GF_OK;
}

#include <string.h>
#include <ctype.h>
#include <stdint.h>

// Assuming GF_Err and related constants are defined elsewhere in the codebase
typedef int GF_Err;
#define GF_OK 0
#define GF_BAD_PARAM -1

typedef struct {
    uint8_t bytes[16];
} bin128;

GF_Err parse_hex_string(const char *string, bin128 *value) {
    const char *ptr = string;
    int length = 0;

    // Check if the string starts with "0x"
    if (ptr && *ptr == '0' && *(ptr + 1) == 'x') {
        ptr += 2;
    }

    // Process the string in pairs of characters
    while (*ptr && length < 16) {
        char byte_str[3] = { *ptr, *(ptr + 1), '\0' };
        char *end;
        unsigned long byte_val = strtoul(byte_str, &end, 16);

        if (end != byte_str + 2) {
            return GF_BAD_PARAM;
        }

        value->bytes[length++] = (uint8_t)byte_val;
        ptr += 2;
    }

    // Check if the string ends correctly (no more characters after the last pair)
    if (*ptr != '\0') {
        return GF_BAD_PARAM;
    }

    // Check if the resulting array contains exactly 16 bytes
    if (length != 16) {
        return GF_BAD_PARAM;
    }

    return GF_OK;
}
